"""Puntos de entrada de la entrega."""

from pathlib import Path
import os

from admision_tp.buscador import BuscadorBM25
from admision_tp.prompts import RAIZ, RUTA_BASELINE, PromptSpec


def construir_buscador(ruta_normas: Path) -> BuscadorBM25:
    return BuscadorBM25(ruta_normas, variante=os.getenv("BUSCADOR_VARIANTE", "baseline"))


def cargar_prompt() -> PromptSpec:
    """PromptSpec de `PROMPT_SPEC` (relativa a la raíz del repo) o el baseline; valida su sha256."""
    ruta = Path(os.getenv("PROMPT_SPEC") or RUTA_BASELINE)
    return PromptSpec.cargar(ruta if ruta.is_absolute() else RAIZ / ruta)


def construir_agente():
    from admision_tp.agente_prompt import AgentePrompt
    from admision_tp.configuracion import Configuracion
    from admision_tp.modelo import ModeloLocal

    prompt = cargar_prompt()  # antes de cargar el modelo: un prompt inválido falla sin usar la GPU
    return AgentePrompt(ModeloLocal.cargar(Configuracion.desde_entorno()), prompt)

def _tokens(texto: str) -> list[str]:
    normalizado = unicodedata.normalize("NFD", texto.casefold())
    sin_tildes = "".join(c for c in normalizado if unicodedata.category(c) != "Mn")
    return re.findall(r"[a-z0-9]+", sin_tildes)


@dataclass(frozen=True)
class ConfigBM25:
    """Cómo se indexa y cuántas secciones ve el agente.

    prefijo: trunca cada término no numérico a sus primeras letras (stemming por prefijo).
    umbral_relativo: descarta secciones con puntaje menor que esa fracción del primero.
    """

    sin_comunes: bool = False
    prefijo: int | None = None
    umbral_relativo: float = 0.0
    k_entorno: int = 2


VARIANTES = {
    "baseline": ConfigBM25(),
    "sin_comunes": ConfigBM25(sin_comunes=True),
    "prefijos": ConfigBM25(sin_comunes=True, prefijo=4, umbral_relativo=0.6, k_entorno=3),
}

def __init__(self, ruta_normas: Path, variante: str | ConfigBM25 = "baseline"):
    if isinstance(variante, ConfigBM25):
        self.variante, self.config = "personalizada", variante
    elif variante in VARIANTES:
        self.variante, self.config = variante, VARIANTES[variante]
    else:
        raise ValueError(f"BUSCADOR_VARIANTE debe ser una de: {', '.join(VARIANTES)}")
    self.k_entorno = self.config.k_entorno
    self._secciones = cargar_normas(Path(ruta_normas))
    self._frecuencias = [Counter(self._terminos(s.texto)) for s in self._secciones]
    self._longitudes = [sum(f.values()) for f in self._frecuencias]
    self._promedio = sum(self._longitudes) / len(self._longitudes) if self._longitudes else 0
    documentos = Counter(t for f in self._frecuencias for t in f)
    n = len(self._secciones)
    self._idf = {t: math.log(1 + (n - df + 0.5) / (df + 0.5)) for t, df in documentos.items()}

def _terminos(self, texto: str) -> list[str]:
    c = self.config
    terminos = [t for t in _tokens(texto) if not (c.sin_comunes and t in PALABRAS_COMUNES)]
    if c.prefijo:
        terminos = [t if t.isdigit() else t[:c.prefijo] for t in terminos]
    return terminos

def recuperar(self, consulta: str, k: int) -> list[Seccion]:
    """Devuelve hasta k secciones por relevancia BM25 (k1=1.5, b=0.75)."""
    if k <= 0 or not self._promedio:
        return []
    terminos = sorted(set(self._terminos(consulta)))
    puntuados = []
    for i, frecuencias in enumerate(self._frecuencias):
        normalizador = 1.5 * (0.25 + 0.75 * self._longitudes[i] / self._promedio)
        puntaje = sum(
            self._idf[t] * frecuencias[t] * 2.5 / (frecuencias[t] + normalizador)
            for t in terminos if t in frecuencias
        )
        if puntaje > 0:
            puntuados.append((i, puntaje))
    puntuados.sort(key=lambda x: (-x[1], x[0]))
    if puntuados:
        minimo = self.config.umbral_relativo * puntuados[0][1]
        puntuados = [(i, p) for i, p in puntuados if p >= minimo]
    return [self._secciones[i] for i, _ in puntuados[:k]]

def cargar_parametros(ruta: Path) -> dict[str, str]:
    """{código: valor con su unidad}, desde `ruta/parametros.yaml`."""
    datos = yaml.safe_load((Path(ruta) / "parametros.yaml").read_text(encoding="utf-8"))
    return {p["codigo"]: valor_como_texto(p["valor"], p["unidad"]) for p in datos["parametros"]}


def linea_de_valores(cuerpo: str, valores: dict[str, str]) -> str:
    """«Valores: P-TDE-3 = 15 min; P-TDE-4 = 60 min.» con los parámetros que cita el cuerpo, en orden de aparición."""
    citados = list(dict.fromkeys(f"{prefijo}-{n}" for prefijo, desde, hasta in PATRON_PARAMETRO.findall(cuerpo)
                                 for n in range(int(desde), int(hasta or desde) + 1)))
    return ("Valores: " + "; ".join(f"{c} = {valores[c]}" for c in citados) + ".") if citados else ""


def cargar_normas(ruta: Path) -> list[Seccion]:
    """Las secciones de `ruta`, en orden alfabético de archivo."""
    valores = cargar_parametros(ruta)
    secciones = []
    for archivo in sorted(Path(ruta).glob("NOR-*.md")):
        cuerpo = archivo.read_text(encoding="utf-8").strip()
        secciones.append(Seccion(archivo.stem, cuerpo, linea_de_valores(cuerpo, valores)))
    return secciones

def ngramas(texto):
    """Caracteres 3..5 dentro de cada palabra alfanumérica, con espacios de borde."""
    cuentas = Counter()
    for palabra in _tokens(texto):
        palabra = f" {palabra} "
        for n in range(3, 6):
            # Las palabras más cortas que n aportan la palabra acolchada una vez.
            if len(palabra) < n:
                continue
            cuentas.update(palabra[i:i + n] for i in range(len(palabra) - n + 1))
    return cuentas


class FusionLexica:
    """Alternativa experimental, no seleccionable desde entrega.py. RRF igual, c=60."""

    k_entorno = 2

    def __init__(self, ruta):
        self.bm25 = BuscadorBM25(ruta, variante="sin_comunes")
        self.secciones = self.bm25._secciones
        cuentas = [ngramas(s.texto) for s in self.secciones]
        df = Counter(g for c in cuentas for g in c)
        self.idf = {g: math.log((1 + len(cuentas)) / (1 + f)) + 1 for g, f in df.items()}
        self.vectores = [self.vector(c) for c in cuentas]

    def vector(self, cuentas):
        pesos = {g: f * self.idf[g] for g, f in cuentas.items() if g in self.idf}
        norma = math.sqrt(sum(p * p for p in pesos.values()))
        return {g: p / norma for g, p in pesos.items()} if norma else {}

    def recuperar(self, consulta, k):
        if k <= 0:
            return []
        q = self.vector(ngramas(consulta))
        cosenos = [(s.id, sum(v.get(g, 0) * p for g, p in q.items()))
                   for s, v in zip(self.secciones, self.vectores)]
        cosenos = sorted(((i, p) for i, p in cosenos if p > 0), key=lambda x: (-x[1], x[0]))
        rankings = [[s.id for s in self.bm25.recuperar(consulta, len(self.secciones))],
                    [i for i, _ in cosenos]]
        rrf = Counter()
        for ranking in rankings:
            for puesto, codigo in enumerate(ranking, 1):
                rrf[codigo] += 1 / (60 + puesto)
        orden = sorted(rrf, key=lambda i: (-rrf[i], i))[:k]

class AgentePrompt:
    """Mismo protocolo JSON y contrato de lotes que el agente de referencia.

    `max_turnos=None` lo deriva del tope de llamadas del kit. Si `modelo_lote` ofrece
    `medir_contexto(conversacion) -> (tokens, limite)`, antes de cada llamada se termina sin
    decisión cada caso que no entra; los demás casos del lote siguen.
    """

    def __init__(self, modelo_lote, prompt: PromptSpec, max_turnos: int | None = None,
                 max_sin_json: int = 3, max_llamadas: int = MAX_LLAMADAS):
        if not isinstance(prompt, PromptSpec):
            raise TypeError("prompt debe ser PromptSpec")
        if max_turnos is None:
            max_turnos = max_turnos_para(max_llamadas, max_sin_json)
        self.modelo_lote = modelo_lote
        self.prompt = prompt
        self.max_turnos = max_turnos
        self.max_sin_json = max_sin_json
        self.max_llamadas = max_llamadas

    @property
    def identidad_prompt(self) -> dict:
        """Identidad que deben guardar los futuros manifiestos de experimentos."""
        return {"nombre": self.prompt.nombre, "version": self.prompt.version, "sha256": self.prompt.sha256}

    def _activas(self, partidas: list) -> list:
        activas = [partida for partida in partidas if partida.activa]
        medir = getattr(self.modelo_lote, "medir_contexto", None)
        if medir is None:
            return activas
        for partida in activas:
            tokens, limite = medir(partida.mensajes)
            if tokens > limite:
                partida.cortar_por_contexto(tokens, limite)
        return [partida for partida in activas if partida.activa]

    def jugar_lote(self, entornos: list) -> list[list[dict]]:
        partidas = [_PartidaPrompt(e, self.prompt, self.max_turnos, self.max_sin_json, self.max_llamadas)
                    for e in entornos]
        while activas := self._activas(partidas):
            conversaciones = [partida.mensajes for partida in activas]
            for partida, respuesta in zip(activas, self.modelo_lote(conversaciones), strict=True):
                partida.recibir(respuesta)
        return [partida.mensajes for partida in partidas]

@dataclass(frozen=True)
class PromptSpec:
    """Todo texto configurable que el coordinador agrega a la conversación.

    El hash cubre la versión del formato y los cuatro textos que afectan al modelo.
    `nombre` es una etiqueta humana y no modifica la identidad del contenido.
    """

    version: int
    nombre: str
    system_prompt: str
    mensaje_inicial: str
    formato_observacion: str
    mensaje_json_invalido: str

    def __post_init__(self):
        if type(self.version) is not int or self.version <= 0:
            raise ValueError("version requiere un entero positivo")
        if not isinstance(self.nombre, str) or not re.fullmatch(r"[a-z0-9][a-z0-9._-]*", self.nombre):
            raise ValueError("nombre de prompt inválido")
        textos = (self.system_prompt, self.mensaje_inicial,
                  self.formato_observacion, self.mensaje_json_invalido)
        if any(not isinstance(texto, str) or not texto.strip() for texto in textos):
            raise ValueError("los textos del prompt no pueden estar vacíos")
        if _placeholders(self.mensaje_inicial) != {"paciente_id"}:
            raise ValueError("mensaje_inicial requiere únicamente {paciente_id}")
        if _placeholders(self.formato_observacion) != {"herramienta", "observacion"}:
            raise ValueError("formato_observacion requiere {herramienta} y {observacion}")

    def _contenido(self) -> dict:
        return {
            "version": self.version,
            "system_prompt": self.system_prompt,
            "mensaje_inicial": self.mensaje_inicial,
            "formato_observacion": self.formato_observacion,
            "mensaje_json_invalido": self.mensaje_json_invalido,
        }

    @property
    def sha256(self) -> str:
        contenido = json.dumps(
            self._contenido(), ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        return hashlib.sha256(contenido).hexdigest()

def desglose(mensajes: list[dict], prompt: PromptSpec) -> dict:
    """`caracteres_de_contexto` repartido por tipo de mensaje; la suma es el total del kit."""
    partes = Counter({parte: 0 for parte in PARTES})
    restantes = sum(m["role"] == "assistant" for m in mensajes)
    herramienta = None
    for i, mensaje in enumerate(mensajes):
        contenido = str(mensaje["content"])
        if mensaje["role"] == "assistant":
            restantes -= 1
            parte, obj = "respuestas", extraer_json(contenido)
            herramienta = str(obj.get("herramienta", "")) if obj else None
        elif i == 0:
            parte = "sistema"
        elif i == 1:
            parte = "inicial"
        elif contenido == prompt.mensaje_json_invalido:
            parte = "correcciones"
        else:
            parte = "busquedas" if herramienta == "buscar_normativa" else "otras_observaciones"
        partes[parte] += len(contenido) * restantes
    if sum(partes.values()) != caracteres_de_contexto(mensajes):
        raise RuntimeError("el desglose no coincide con caracteres_de_contexto")
    return dict(partes)

def _verificar_origen(casos, esperadas, normas, proposito) -> dict:
    """Guardas previas a copiar cualquier entrada; devuelve qué se verificó.

    Las rutas se resuelven (incluidos symlinks) antes de comparar con ``practica/``. El
    chequeo del kit se corre sobre las rutas ORIGINALES: la copia en ``salida/entradas``
    nunca tiene esperadas al lado y por eso no lo dispararía.
    """
    if proposito not in PROPOSITOS:
        raise ValueError(f"propósito inválido; usar uno de {', '.join(PROPOSITOS)}")
    practica = _PRACTICA.resolve()
    en_practica = []
    for nombre, ruta in (("casos", casos), ("esperadas", esperadas)):
        resuelta = Path(ruta).resolve()
        if resuelta == practica or practica in resuelta.parents:
            en_practica.append(nombre)
    if proposito == "plomeria":
        # Solo plomería puede usar práctica; la copia aislada sigue revisada por `jugar`.
        return {"datos_practica": en_practica, "esperadas_al_alcance": "omitida_plomeria"}
    if en_practica:
        raise ValueError(
            f"{' y '.join(en_practica)} dentro de practica/: nunca se evalúan ni optimizan prompts "
            "con práctica; para probar solo la plomería usar --solo-plomeria")
    revisar_que_no_haya_esperadas(Path(normas), Path(casos))
    return {"datos_practica": [], "esperadas_al_alcance": "verificada_en_origen"}

