        try:
            frs = self.buscador.recuperar(consulta, getattr(self.buscador, "k_entorno", K_POR_DEFECTO))
            return "\n\n".join(_texto(f) for f in frs) if frs else "No se encontró ninguna sección."
        except Exception as e:  # un error del buscador del grupo no corta la corrida
            raise ValueError(f"el buscador falló: {type(e).__name__}.") from e
    if h == "registrar_decision":

CONTROLES = CAMPOS + ["verificacion"]


def _doc(x) -> str | None:
    return None if x is None else "".join(ch for ch in str(x).upper() if ch.isalnum())


def _igual(campo: str, esperado, obtenido) -> bool:
    if campo == "numero_documento":
        return _doc(esperado) == _doc(obtenido)
    if campo == "entidad_a_notificar":
        return (esperado is None and obtenido is None) or (
            esperado is not None and obtenido is not None and _norm(esperado) == _norm(obtenido))
    return esperado == obtenido


def _verifico(verificacion: dict, log: list[dict]) -> bool:
    hechas = [(_norm(e["argumentos"].get("entidad", "")), _norm(e["argumentos"].get("numero_afiliado", "")))
              for e in log if e["herramienta"] == "verificar_afiliacion" and isinstance(e["argumentos"], dict)]
    if any(e in {_norm(x) for x in verificacion["prohibidas"]} for e, _ in hechas):
        return False
    requerida = verificacion["requerida"]
    return requerida is None or (_norm(requerida[0]), _norm(requerida[1])) in hechas


def comparar(esperada: dict, decision: dict | None, log: list[dict]) -> dict:
    ficha = esperada["ficha"]
    if decision is None:
        controles = {k: False for k in CONTROLES}
    else:
        controles = {k: _igual(k, ficha[k], decision.get(k)) for k in CAMPOS}
        controles["verificacion"] = _verifico(esperada["verificacion"], log)
    return {
        "caso": esperada["caso"],
        "resuelto": all(controles.values()),
        "parcial": round(sum(controles.values()) / len(controles), 3),
        "controles": controles,
        "esperada": ficha,
        "obtenida": decision,
        "llamadas": len(log),
        "invalidas": sum(not e["valida"] for e in log),
    }

def circuito_esperado(row: dict[str, str]) -> str:
    if row["sospecha_sepsis"] != "no":
        return "codigo_sepsis"
    if row["motivo"] == "dolor tor\u00e1cico":
        return "ecg"
    if row["motivo"] == "signos neurol\u00f3gicos focales de inicio s\u00fabito":
        return "codigo_acv"
    return "ninguno"


def plazo_esperado(row: dict[str, str], parametros: dict[str, int]) -> str:
    circuito = circuito_esperado(row)
    bases = {
        "ecg": parametros["P-TDE-1"],
        "codigo_acv": parametros["P-TDE-2"],
        "codigo_sepsis": (
            parametros["P-TDE-3"]
            if row["sospecha_sepsis"] in {"probable", "con signos de shock"}
            else parametros["P-TDE-4"]
        ),
    }
    if circuito == "ninguno":
        return ""
    descuento = parametros["P-TDE-5"] if row["llegada"] == "en ambulancia" else 0
    return str(bases[circuito] - descuento)


def registro_esperado(row: dict[str, str], parametros: dict[str, int]) -> str:
    if not row["documento_tipo"]:
        return "provisorio"
    if row["documento_tipo"] == "DNI":
        return "definitivo"
    return "provisorio" if int(row["nivel"]) <= parametros["P-ADM-3"] else "definitivo"

def tokenizar_conversacion(registro, tokenizer, max_seq_length):
    """Incluye respuesta y cierre del turno; excluye encabezados y todo contexto.

    Solo acepta plantillas/tokenizadores que preserven exactamente sus prefijos.
    No pide máscaras nativas (Gemma fijado no tiene bloques generation).
    """
    validar_registro(registro)
    if type(max_seq_length) is not int or max_seq_length <= 0:
        raise ValueError("max_seq_length requiere entero positivo")
    mensajes = registro["messages"]

    def tokens(historia, generar=False):
        salida = tokenizer.apply_chat_template(
            historia, tokenize=True, add_generation_prompt=generar,
            enable_thinking=False, padding=False, truncation=False, return_dict=True)
        ids = salida["input_ids"]
        if not isinstance(ids, list) or not ids or any(type(x) is not int or x < 0 for x in ids):
            raise ValueError("tokenizador devolvió IDs inválidos o anidados")
        if salida.get("attention_mask", [1] * len(ids)) != [1] * len(ids):
            raise ValueError("tokenización individual no debe contener padding")
        return ids

    ids = tokens(mensajes)
    if len(ids) > max_seq_length:
        raise ValueError("conversación excede max_seq_length; no se recorta")
    labels = [-100] * len(ids)
    for i, mensaje in enumerate(mensajes):
        if mensaje["role"] != "assistant":
            continue
        inicio = tokens(mensajes[:i], True)
        fin = tokens(mensajes[:i + 1])
        if ids[:len(inicio)] != inicio or ids[:len(fin)] != fin or len(fin) <= len(inicio):
            raise ValueError("plantilla/tokenizador no preserva prefijos; máscara insegura")
        labels[len(inicio):len(fin)] = ids[len(inicio):len(fin)]
    if all(x == -100 for x in labels):
        raise ValueError("conversación sin tokens supervisados")
    return {"input_ids": ids, "attention_mask": [1] * len(ids), "labels": labels}

# Solo la atención del modelo de lenguaje. Gemma 4 es multimodal: sus torres de visión y audio también
